using UnityEngine;using DG.Tweening;using LWS.TruckSports;
namespace LWS.TruckMattressRacing {
public enum MattressAttempt {Waiting,Racing,Recovery,Finished,DNF,Inactive}
public sealed class MattressRacer:MonoBehaviour {
 public MattressMatch match;public SportsEventTruck truck;public int slot;public Transform cushion;public Collider pad;public PhysicsMaterial slideMaterial,braceMaterial;public MattressAttempt Phase{get;private set;}public int Checkpoint{get;private set;}public int Recoveries{get;private set;}public Vector3 FinishOrigin{get;private set;}public float FinishTime{get;private set;}=float.PositiveInfinity;public float RecoveryRemaining{get;private set;}public bool Grounded=>groundAge>0;public bool Bracing{get;private set;}
 PhysicsMaterial ownedSlide,ownedBrace;void Awake(){ownedSlide=Instantiate(slideMaterial);ownedBrace=Instantiate(braceMaterial);}
 Vector3 previous;float groundAge,tipped,stalled,impactAge;Vector3 normal=Vector3.up;Tween wobble;
 public void Prepare(bool active){Phase=active?MattressAttempt.Waiting:MattressAttempt.Inactive;Checkpoint=Recoveries=0;FinishTime=float.PositiveInfinity;tipped=stalled=groundAge=0;wobble?.Kill();cushion.localScale=Vector3.one;truck.visuals.gameObject.SetActive(active);cushion.gameObject.SetActive(active);truck.Prepare(match.course.Spawn(slot,0),match.course.Rotation(0),false);truck.body.isKinematic=true;truck.body.detectCollisions=active;Bracing=false;previous=truck.body.position;}
 public void Release(){if(Phase!=MattressAttempt.Waiting)return;Phase=MattressAttempt.Racing;truck.body.isKinematic=false;truck.body.WakeUp();}
 public void Step(Vector2 lean,bool brace,float dt){if(Phase==MattressAttempt.Recovery){RecoveryRemaining-=dt;if(RecoveryRemaining<=0){Phase=MattressAttempt.Racing;truck.body.detectCollisions=true;truck.body.isKinematic=false;truck.body.WakeUp();}return;}if(Phase==MattressAttempt.Finished){truck.body.AddForce(-Vector3.ProjectOnPlane(truck.body.linearVelocity,Vector3.up)*.9f,ForceMode.Acceleration);return;}if(Phase!=MattressAttempt.Racing)return;var body=truck.body;groundAge=Mathf.Max(0,groundAge-dt);Bracing=brace;float surface=match.course.ContactFactor(body.position)*match.course.weather.Grip;ownedSlide.staticFriction=ownedSlide.dynamicFriction=.075f*surface;ownedBrace.staticFriction=ownedBrace.dynamicFriction=.11f*surface;pad.sharedMaterial=brace?ownedBrace:ownedSlide;body.angularDamping=brace?2.6f:.25f;body.centerOfMass=Vector3.MoveTowards(body.centerOfMass,new Vector3(lean.x*.28f,.08f,lean.y*.32f),dt*.8f);float speed=Vector3.ProjectOnPlane(body.linearVelocity,Vector3.up).magnitude;
 // Cloth carving is bounded contact response. Gravity supplies all down-course propulsion.
 if(Grounded){var right=Vector3.ProjectOnPlane(transform.right,normal).normalized;float side=Vector3.Dot(body.linearVelocity,right);body.AddForce(right*Mathf.Clamp(lean.x*1.1f-side*.75f,-2,2)*match.course.weather.Grip,ForceMode.Acceleration);body.AddTorque(normal*lean.x*Mathf.Clamp(speed*.09f,.3f,2.1f),ForceMode.Acceleration);if(brace)body.AddForce(Vector3.ClampMagnitude(-Vector3.ProjectOnPlane(body.linearVelocity,normal)*.18f,7),ForceMode.Acceleration);}body.AddTorque(transform.right*(lean.y*.75f)-transform.forward*lean.x*.3f,ForceMode.Acceleration);body.AddForce(match.course.weather.Flow*.08f,ForceMode.Acceleration);
 float z=body.position.z;while(Checkpoint<match.course.checkpoints.Length&&previous.z<match.course.checkpoints[Checkpoint]&&z>=match.course.checkpoints[Checkpoint]){float gate=match.course.checkpoints[Checkpoint];float x=Mathf.Lerp(previous.x,body.position.x,Mathf.InverseLerp(previous.z,z,gate));if(Mathf.Abs(x-match.course.Center(gate))>=46)break;Checkpoint++;}if(Checkpoint==match.course.checkpoints.Length&&z>=MattressCourse.Finish){Phase=MattressAttempt.Finished;FinishTime=match.RaceTime-dt+Mathf.InverseLerp(previous.z,z,MattressCourse.Finish)*dt;FinishOrigin=truck.body.position;match.Arrived(this);return;}
 tipped=Vector3.Dot(transform.up,Vector3.up)<.2f?tipped+dt:Mathf.Max(0,tipped-dt);stalled=match.RaceTime>5&&speed<.7f?stalled+dt:0;if(tipped>3||stalled>7||Mathf.Abs(body.position.x)>63||body.position.y<match.course.Height(body.position)-7||Checkpoint<match.course.checkpoints.Length&&z>match.course.checkpoints[Checkpoint]+20)Recover();previous=body.position;}
 public void Recover(){if(Phase!=MattressAttempt.Racing)return;if(Recoveries>=3){Fail();return;}Recoveries++;Phase=MattressAttempt.Recovery;RecoveryRemaining=5;truck.body.linearVelocity=truck.body.angularVelocity=Vector3.zero;truck.body.isKinematic=true;truck.body.detectCollisions=false;float z=Checkpoint==0?0:match.course.checkpoints[Checkpoint-1]-2;truck.body.position=match.course.Spawn(slot,z);truck.body.rotation=match.course.Rotation(z);truck.body.centerOfMass=new Vector3(0,.08f,0);previous=truck.body.position;tipped=stalled=0;match.Recovered(this);}
 public void Fail(){if(Phase==MattressAttempt.Finished||Phase==MattressAttempt.Inactive)return;Phase=MattressAttempt.DNF;truck.body.isKinematic=true;truck.body.detectCollisions=false;truck.visuals.gameObject.SetActive(false);cushion.gameObject.SetActive(false);}
 void OnCollisionStay(Collision c){for(int i=0;i<c.contactCount;i++){var n=c.GetContact(i).normal;if(n.y>.3f){groundAge=.08f;normal=n;break;}}}
 void OnCollisionEnter(Collision c){if(Phase!=MattressAttempt.Racing)return;float impact=c.relativeVelocity.magnitude;if(impact>2&&Time.time-impactAge>.18f){impactAge=Time.time;wobble?.Kill();cushion.localScale=Vector3.one;float amount=Mathf.Clamp(impact/18,.025f,.17f);wobble=cushion.DOPunchScale(new Vector3(amount*.3f,-amount,amount*.3f),.65f,3,.45f).SetLink(gameObject);match.Impact(slot,impact);}}
 public void Stop(){wobble?.Kill();truck.Power(false);if(!truck.body.isKinematic)truck.body.linearVelocity=truck.body.angularVelocity=Vector3.zero;truck.body.isKinematic=true;truck.StopSound();}void OnDestroy(){wobble?.Kill();if(ownedSlide!=null)Destroy(ownedSlide);if(ownedBrace!=null)Destroy(ownedBrace);}
}
}
